import java.util.*;

// Indexed/random access workload -> ArrayList (O(1) get)
List<Integer> list = new ArrayList<>(100_000);
for (int i = 0; i < 100_000; i++) list.add(i);
long sum = 0;
for (int i = 0; i < list.size(); i++) sum += list.get(i); // O(n) total

// Pure head/tail queue work -> ArrayDeque (O(1) ends, cache-friendly)
Deque<String> queue = new ArrayDeque<>();
queue.addLast("job-1");          // enqueue
String next = queue.pollFirst(); // dequeue, O(1)
