Match the structure to the hot operation: ArrayList for indexed reads, ArrayDeque/LinkedList for head-tail churn, never Vector in new code.

import java.util.ArrayList;
import java.util.List;

public class ArrayListResizeDemo {
    public static void main(String[] args) {
        // Default initial capacity is 10
        List<String> orders = new ArrayList<>();

        // Add 10 elements - no resize yet
        for (int i = 1; i <= 10; i++) {
            orders.add("Order-" + i);
        }

        // 11th element triggers resize: 10 -> 15 (10 + 10/2)
        orders.add("Order-11");

        // Continue to 15 elements - no resize
        for (int i = 12; i <= 15; i++) {
            orders.add("Order-" + i);
        }

        // 16th element triggers resize: 15 -> 22 (15 + 15/2)
        orders.add("Order-16");

        // Alternative: if you know size upfront, avoid resizes
        List<String> largeOrders = new ArrayList<>(1000);
        for (int i = 0; i < 1000; i++) {
            largeOrders.add("Order-" + i);  // No resizes during this loop
        }
    }
}

import java.util.Deque;
import java.util.LinkedList;

public class LinkedListDequeDemo {
    public static void main(String[] args) {
        Deque<String> orderQueue = new LinkedList<>();

        // Use as a FIFO queue
        orderQueue.addLast("Order-101");   // O(1) - add to tail
        orderQueue.addLast("Order-102");
        orderQueue.addLast("Order-103");
        String processed = orderQueue.removeFirst();  // O(1) - remove from head
        // processed = "Order-101"

        // Use as a LIFO stack
        Deque<String> undoStack = new LinkedList<>();
        undoStack.addFirst("Action-1");    // O(1) - push to front
        undoStack.addFirst("Action-2");
        String lastAction = undoStack.removeFirst();  // O(1) - pop from front
        // lastAction = "Action-2"

        // Use as a double-ended queue
        Deque<String> taskDeque = new LinkedList<>();
        taskDeque.addFirst("High-priority");  // Urgent task at front
        taskDeque.addLast("Low-priority");    // Regular task at back
        String urgent = taskDeque.removeFirst();     // Process urgent
        String regular = taskDeque.removeLast();     // Cancel low-priority
    }
}

import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;

public class VectorReplacementDemo {
    public static void main(String[] args) {
        // Legacy: Vector (synchronized, avoid in new code)
        Vector<String> legacyOrders = new Vector<>();
        legacyOrders.add("Order-1");  // Acquires lock

        // Modern single-threaded: ArrayList
        List<String> orders = new ArrayList<>();
        orders.add("Order-1");  // No lock overhead

        // Modern multi-threaded (method-level sync):
        List<String> syncOrders = Collections.synchronizedList(new ArrayList<>());
        syncOrders.add("Order-1");  // Synchronized like Vector

        // Compound operation still needs external lock
        synchronized (syncOrders) {
            if (!syncOrders.isEmpty()) {
                String first = syncOrders.get(0);  // Safe now
            }
        }

        // Modern concurrent read-heavy: CopyOnWriteArrayList
        List<String> concurrentOrders = new CopyOnWriteArrayList<>();
        concurrentOrders.add("Order-1");  // Locks only for write
        String read = concurrentOrders.get(0);  // No lock for reads
    }
}

import java.util.ArrayList;
import java.util.List;

public class ArrayListComplexityDemo {
    public static void main(String[] args) {
        List<String> orders = new ArrayList<>();
        orders.add("Order-1");  // Amortized O(1) - write to next slot
        orders.add("Order-2");
        orders.add("Order-3");

        // O(1) - direct array access at index
        String second = orders.get(1);  // "Order-2"

        // O(n) - insert at index 1, shift "Order-2" and "Order-3" right
        orders.add(1, "Order-1.5");
        // Before: [Order-1, Order-2, Order-3]
        // After:  [Order-1, Order-1.5, Order-2, Order-3]

        // O(n) - remove at index 1, shift "Order-2" and "Order-3" left
        orders.remove(1);
        // After:  [Order-1, Order-2, Order-3]

        // O(n) - linear scan comparing each element
        boolean found = orders.contains("Order-2");  // true

        // O(n) worst case - scan until end
        int index = orders.indexOf("Order-3");  // 2
    }
}

